package com.chessapp.ui.board

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Fill
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.translate
import com.chessapp.domain.model.PieceType
import com.chessapp.domain.model.Color as PieceColor

/**
 * Chess pieces rendered from Colin M.L. Burnett's classic set (the pieces used
 * by Wikipedia and Lichess), (C) Colin M.L. Burnett, GPLv2+ - see
 * THIRD_PARTY_LICENSES.md. Geometry is machine-sampled from the original 45x45
 * SVGs into polylines at build-tool time (tools kept out of the app).
 *
 * Rendering keeps this app's readability rule: light pieces are bone with a
 * dark outline, dark pieces charcoal with a light outline, so both read on any
 * square color. role: 0=body (fill+outline), 1=detail stroke, 2=contrast fill.
 */
object PieceRenderer {

    private const val VIEW = 45f

    private class Part(val role: Int, val closed: Boolean, val pts: FloatArray)

    fun draw(
        scope: DrawScope,
        type: PieceType,
        color: PieceColor,
        topLeft: Offset,
        cell: Float
    ) {
        val fill = if (color == PieceColor.WHITE) Color(0xFFF7F3E8) else Color(0xFF2B2B28)
        val line = if (color == PieceColor.WHITE) Color(0xFF1A1A17) else Color(0xFFE8E2D2)
        val pad = cell * 0.06f
        val s = (cell - pad * 2) / VIEW
        val stroke = Stroke(width = 1.5f * s, cap = StrokeCap.Round, join = StrokeJoin.Round)

        scope.translate(topLeft.x + pad, topLeft.y + pad) {
            for (part in partsFor(type, color)) {
                val path = Path().apply {
                    val p = part.pts
                    moveTo(p[0] * s, p[1] * s)
                    var i = 2
                    while (i < p.size) { lineTo(p[i] * s, p[i + 1] * s); i += 2 }
                    if (part.closed) close()
                }
                when (part.role) {
                    0 -> { drawPath(path, fill, style = Fill); drawPath(path, line, style = stroke) }
                    1 -> drawPath(path, line, style = stroke)
                    2 -> drawPath(path, line, style = Fill)
                }
            }
        }
    }

    private fun partsFor(type: PieceType, color: PieceColor): List<Part> =
